-- 003 — Carga inicial: perfis, marcas, lojas, áreas (conteúdo dos guias), indicadores, checklists, cursos,
-- calendário comercial 2026 e dados de demonstração (demo = TRUE, removíveis em Configurações → Sistema).

-- ---------- Perfis (12 do protótipo + Consultor) ----------
INSERT INTO perfis (codigo, nome, ordem, permissoes)
SELECT p->>0, p->>1, (o - 1)::int, jsonb_build_object('exec',(p->>2)::int,'areas',(p->>3)::int,'cal',(p->>4)::int,'acao',(p->>5)::int,'comite',(p->>6)::int,'check',(p->>7)::int,'cms',(p->>8)::int,'rbac',(p->>9)::int)
  FROM jsonb_array_elements($j$[["admin","Super Admin",2,2,2,2,2,2,2,2],["diretor","Diretor",2,2,2,2,2,2,1,1],["ger_regional","Ger. Regional",1,2,2,2,2,2,0,0],["supervisor","Supervisor",1,2,1,2,1,2,0,0],["ger_loja","Ger. Loja",0,2,1,1,0,2,0,0],["marketing","Marketing",1,2,2,1,1,1,2,0],["compras","Compras",0,2,1,1,1,1,0,0],["vm","VM",0,2,1,1,0,2,0,0],["crm","CRM",1,2,1,1,1,0,1,0],["bigpay","BigPay",0,2,1,1,0,0,0,0],["operacao","Operação",0,2,1,2,0,2,0,0],["usuario","Usuário",0,1,1,1,0,1,0,0],["consultor","Consultor",2,2,2,2,2,2,2,1]]$j$::jsonb) WITH ORDINALITY AS t(p, o)
ON CONFLICT (codigo) DO NOTHING;

-- ---------- Marcas e lojas (nomes genéricos — ajustar em Configurações → Lojas) ----------
INSERT INTO marcas (codigo, cor, ordem)
SELECT m->>0, m->>1, (o - 1)::int FROM jsonb_array_elements($j$[["MILLA","#0B3D4D"],["MILLA CASA","#1D4ED8"],["DÁHLIA","#C8102E"],["DOM CORTEZ","#E0A82E"]]$j$::jsonb) WITH ORDINALITY AS t(m, o)
ON CONFLICT DO NOTHING;
INSERT INTO lojas (nome, marca)
SELECT x.marca || ' — Loja ' || lpad(g::text, 2, '0'), x.marca
  FROM (VALUES ('MILLA', 6), ('MILLA CASA', 5), ('DÁHLIA', 4), ('DOM CORTEZ', 3)) AS x(marca, n), generate_series(1, x.n) g
 ORDER BY x.marca, g;

