INSERT INTO areas (id, nome, resp, cargo, cor, grad, ic, tag, papel, ordem, conteudo)
SELECT a->>'id', a->>'nome', a->>'resp', a->>'cargo', a->>'cor', a->>'grad', a->>'ic', a->>'tag', a->>'papel', (a->>'ordem')::int, a->'conteudo'
  FROM carga_areas ON CONFLICT (id) DO NOTHING;

INSERT INTO indicadores (area_id, ordem, nome, valor, variacao, positivo, serie)
SELECT a->>'id', (o - 1)::int, k->>0, k->>1, k->>2, (k->>3)::boolean, k->4
  FROM carga_areas, jsonb_array_elements(a->'kpis') WITH ORDINALITY AS t(k, o);

INSERT INTO checklist_modelos (area_id, nome, itens, ordem)
SELECT a->>'id', c->>0, c->1, (o - 1)::int
  FROM carga_areas, jsonb_array_elements(a->'checklists') WITH ORDINALITY AS t(c, o);

INSERT INTO cursos (area_id, titulo, aulas, duracao, ordem)
SELECT a->>'id', c->>0, (c->>1)::int, c->>2, (o - 1)::int
  FROM carga_areas, jsonb_array_elements(a->'cursos') WITH ORDINALITY AS t(c, o);

