  FROM (VALUES ('Gilberto Santos', 'gilberto', 'diretor', 'Diretor Executivo', NULL, 0),
               ('Ebson', 'ebson', 'ger_regional', 'Gerente Regional', 'regional', 2610),
               ('Gabriela', 'gabriela', 'marketing', 'Gestora de Marketing', 'marketing', 3210),
               ('Kátia Júlia', 'katia.julia', 'crm', 'Gestora de CRM', 'crm', 2970),
               ('Régis', 'regis', 'vm', 'Gestor de VM / PDV', 'vm', 2480),
               ('Jaqueline', 'jaqueline', 'compras', 'Gestora de Compras', 'compras', 2310)) AS p0(nome, login, perfil, cargo, area, pts)
  CROSS JOIN LATERAL (SELECT p0.nome, p0.login || '@demo.academiamilla.tech' AS email, p0.perfil, p0.cargo, p0.area) p
ON CONFLICT (email) DO NOTHING;

