-- Progresso de cursos dos administradores (referência do protótipo)
INSERT INTO curso_progresso (usuario_id, curso_id, aulas_feitas, concluido_em)
SELECT u.id, cu.id, round((c->>1)::int * (c->>3)::numeric / 100)::int, CASE WHEN (c->>3)::int = 100 THEN now() END
  FROM carga_areas CROSS JOIN LATERAL jsonb_array_elements(a->'cursos') WITH ORDINALITY AS t(c, o)
  JOIN cursos cu ON cu.area_id = a->>'id' AND cu.ordem = o - 1
  CROSS JOIN usuarios u
 WHERE u.perfil = 'admin' AND NOT u.demo AND (c->>3)::int > 0
ON CONFLICT DO NOTHING;

-- Plano de ação (datas relativas a hoje)
INSERT INTO acoes (area_id, titulo, status, prioridade, marca, responsavel, inicio, prazo, concluido_em, origem, demo)
SELECT a->>'id', CASE WHEN t.titulo = '#checklist' THEN a->'checklists'->0->>0 ELSE t.titulo END, t.status, t.prio, t.marca, a->>'resp',
       CURRENT_DATE - 14 + t.ini, CURRENT_DATE - 14 + t.fim,
       CASE WHEN t.status = 'Concluído' THEN (CURRENT_DATE - 15 + t.fim)::timestamptz END, 'Plano da área', TRUE
  FROM carga_areas,
       (VALUES ('Preparar campanha da área', 'A fazer', 14, 24, 'MILLA', 'Alta'),
               ('Revisar pendências do comitê', 'A fazer', 24, 33, NULL, 'Média'),
               ('#checklist', 'Em andamento', 7, 21, 'MILLA CASA', 'Alta'),
               ('Acompanhar indicadores do mês', 'Em andamento', 0, 42, NULL, 'Média'),
               ('Enviar evidências ao comitê', 'Em revisão', 18, 26, 'DÁHLIA', 'Média'),
               ('Rotina semanal aplicada', 'Concluído', 0, 7, NULL, 'Baixa'),
               ('Treinamento de equipe', 'Concluído', 5, 12, 'DOM CORTEZ', 'Média')) AS t(titulo, status, ini, fim, marca, prio);

-- Checklists aplicados (3 por área)
INSERT INTO checklist_aplicacoes (modelo_id, area_id, loja_id, respostas, score, qtd_ok, qtd_atencao, qtd_nc, demo, criado_em)
SELECT m.id, m.area_id, (SELECT id FROM lojas ORDER BY id OFFSET ((a.ordem * 3 + k) % 18) LIMIT 1),
       r.resp, round((r.ok + r.w * 0.5) / r.n * 100)::int, r.ok, r.w, r.no, TRUE, now() - make_interval(days => k * 3 + 1)
  FROM areas a CROSS JOIN generate_series(0, 2) k
  JOIN checklist_modelos m ON m.area_id = a.id AND m.ordem = k % (SELECT COUNT(*) FROM checklist_modelos x WHERE x.area_id = a.id)
  CROSS JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object('s', s, 'obs', '') ORDER BY i) AS resp, COUNT(*) AS n,
           COUNT(*) FILTER (WHERE s = 'ok') AS ok, COUNT(*) FILTER (WHERE s = 'warn') AS w, COUNT(*) FILTER (WHERE s = 'no') AS no
      FROM (SELECT i, CASE WHEN (i + k + a.ordem) % 7 = 0 THEN 'warn' WHEN (i + a.ordem * k) % 11 = 5 THEN 'no' ELSE 'ok' END AS s
              FROM generate_series(0, jsonb_array_length(m.itens) - 1) i) q) r;

