-- Conteúdos (CMS)
INSERT INTO conteudos (titulo, tipo, area_id, corpo, status, publicado_em, demo)
SELECT c.t, c.tipo, c.area, c.corpo, c.st, CASE WHEN c.st = 'Publicado' THEN now() END, TRUE
  FROM (VALUES ('Nova política de VM para a próxima campanha', 'Comunicado', 'vm', 'Publicado', 'As lojas devem seguir o guia rápido de montagem e enviar as fotos-padrão em até 48h após a montagem.'),
               ('Banner da campanha do mês', 'Banner', 'marketing', 'Publicado', 'Banner principal da campanha vigente.'),
               ('Manual de atendimento 2026', 'Página', 'comercial', 'Rascunho', 'Padrão de abordagem, venda assistida e oferta de cartão no caixa.'),
               ('Régua de recompra do mês', 'Página', 'crm', 'Publicado', 'Cadência de mensagens por público: ativos, inativos e VIP.'),
               ('OTB do próximo trimestre — rascunho', 'Página', 'compras', 'Rascunho', 'Orçamento de compra por linha (em elaboração).')) AS c(t, tipo, area, st, corpo);
